WITH valid AS (SELECT *, CAST(reading_ts AS DATE) AS reading_ts_day, DATE_FORMAT(reading_ts, 'yyyy-MM-dd') AS reading_ts_label FROM device_readings WHERE reading_ts >= TIMESTAMP '2025-09-01 02:00:00' AND firmware = '2.0.1') SELECT id, temp_c, humidity, status_bits, reading_ts_day, LEAD(humidity, 2) OVER (PARTITION BY device_code ORDER BY pressure, id) AS next_humidity, LEAD(temp_c, 1, 0) OVER (PARTITION BY device_code ORDER BY reading_ts_day, id) AS next_temp_c, DENSE_RANK() OVER (ORDER BY humidity DESC) AS humidity_dense_rank, NTILE(4) OVER (PARTITION BY device_code ORDER BY temp_c, id) AS temp_c_bucket, AVG(humidity) OVER (ORDER BY temp_c, id ROWS BETWEEN 2 PRECEDING AND 1 PRECEDING) AS humidity_avg_2_prior FROM valid;
